// Prints src/fx/true_peak_taps.inc: the three polyphase rows (phases 1/4,
// 1/2, 3/4 at the unity-step cutoff) the true-peak detector interpolates
// with, as exact hex-float literals. Built by the host test build; run by
// scripts/gen-true-peak-taps.sh. `true_peak_taps_match_sinc_table` in
// bus_fx_tests pins the committed file to `sinc_row` output.

#include "resampler.h"

#include <cstdio>

int main() {
  using namespace media_engine;
  const double cutoff = sinc_cutoff_for_step(1.0);
  std::printf(
      "// Generated by native/media_engine/tools/gen_true_peak_taps.cpp\n"
      "// (scripts/gen-true-peak-taps.sh). Do not edit by hand.\n"
      "//\n"
      "// Rows %d, %d and %d of sinc_table(sinc_cutoff_for_step(1.0)): the 4x\n"
      "// oversampling phases of the BS.1770-4 true-peak detector. Static data, so\n"
      "// building a limiter or a meter never builds the %d-row Kaiser table.\n"
      "// clang-format off\n",
      kSincPhases / 4, kSincPhases / 2, 3 * kSincPhases / 4, kSincPhases + 1);
  for (int k = 1; k <= 3; ++k) {
    float row[kSincTaps];
    sinc_row(cutoff, k * kSincPhases / 4, row);
    std::printf("{\n");
    for (int j = 0; j < kSincTaps; ++j) {
      std::printf("%s%af%s", j % 4 == 0 ? "  " : "", static_cast<double>(row[j]),
                  j + 1 == kSincTaps ? "\n" : (j % 4 == 3 ? ",\n" : ", "));
    }
    std::printf("}%s\n", k < 3 ? "," : "");
  }
  std::printf("// clang-format on\n");
  return 0;
}
